-- A Gateway is not allowed to become active solely through an administrator
-- action.  It must prove possession of the certificate registered here and a
-- short-lived, one-time enrollment secret generated by the control plane.
ALTER TABLE gateways
    ADD COLUMN IF NOT EXISTS certificate_fingerprint TEXT,
    ADD COLUMN IF NOT EXISTS enrollment_public_key TEXT,
    ADD COLUMN IF NOT EXISTS enrollment_token_hash TEXT,
    ADD COLUMN IF NOT EXISTS enrollment_expires_at TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS activated_at TIMESTAMPTZ;

-- Earlier builds had no proof binding. Re-enrollment is intentionally
-- required instead of continuing to trust a manually activated endpoint.
UPDATE gateways
SET status = 'pending',
    last_seen_at = NULL,
    activated_at = NULL
WHERE certificate_fingerprint IS NULL OR enrollment_public_key IS NULL;

ALTER TABLE gateways
    DROP CONSTRAINT IF EXISTS gateways_active_requires_enrollment;
ALTER TABLE gateways
    ADD CONSTRAINT gateways_active_requires_enrollment
    CHECK (
        status <> 'active'
        OR (
            certificate_fingerprint IS NOT NULL
            AND enrollment_public_key IS NOT NULL
            AND activated_at IS NOT NULL
            AND enrollment_token_hash IS NULL
        )
    );

CREATE INDEX IF NOT EXISTS idx_gateways_pending_enrollment_expiry
    ON gateways(enrollment_expires_at)
    WHERE status = 'pending';
